def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "neg": 3,
        ":": 4,
    }
    token_pattern = re.compile(r"\d+|[A-Z][A-Z0-9]*|<>|<=|>=|[^\s]")

    def integer(text):
        try:
            return int(text)
        except ValueError:
            # Avoid Python's decimal-string digit limit for large literals.
            text = text.strip()
            sign = -1 if text.startswith("-") else 1
            if text[:1] in ("+", "-"):
                text = text[1:]
            value = 0
            for i in range(0, len(text), 9):
                chunk = text[i:i + 9]
                value = value * (10 ** len(chunk)) + int(chunk)
            return sign * value

    def parse(formula):
        nodes = []
        operators = []
        argument_counts = []
        expecting_operand = True

        def reduce_operator():
            op = operators.pop()
            right = nodes.pop()
            if op == "neg":
                nodes.append(("neg", right))
            else:
                left = nodes.pop()
                nodes.append((op, left, right))

        for match in token_pattern.finditer(formula):
            token = match.group()

            if token[0].isdigit():
                nodes.append(("number", integer(token)))
                expecting_operand = False
            elif token in functions:
                operators.append(token)
                expecting_operand = True
            elif token[0].isalpha():
                nodes.append(("reference", token))
                expecting_operand = False
            elif token == "(":
                operators.append("(")
                argument_counts.append(1)
                expecting_operand = True
            elif token == ",":
                while operators[-1] != "(":
                    reduce_operator()
                argument_counts[-1] += 1
                expecting_operand = True
            elif token == ")":
                while operators[-1] != "(":
                    reduce_operator()
                operators.pop()
                count = argument_counts.pop()
                if operators and operators[-1] in functions:
                    function = operators.pop()
                    arguments = tuple(nodes[-count:])
                    del nodes[-count:]
                    nodes.append((function, arguments))
                expecting_operand = False
            else:
                op = "neg" if token == "-" and expecting_operand else token
                while (
                    operators
                    and operators[-1] in precedence
                    and (
                        precedence[operators[-1]] > precedence[op]
                        or (
                            precedence[operators[-1]] == precedence[op]
                            and op != "neg"
                        )
                    )
                ):
                    reduce_operator()
                operators.append(op)
                expecting_operand = True

        while operators:
            reduce_operator()
        return nodes[0]

    def expanded_arguments(arguments):
        for argument in arguments:
            if argument[0] != ":":
                yield argument
                continue

            first = argument[1][1]
            second = argument[2][1]
            left, right = sorted((ord(first[0]), ord(second[0])))
            top, bottom = sorted((int(first[1:]), int(second[1:])))

            for row in range(top, bottom + 1):
                for column in range(left, right + 1):
                    name = chr(column) + str(row)
                    if name in cells:
                        yield ("reference", name)

    def binary(op, left, right):
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        if op == "*":
            return left * right
        if op == "/":
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient
        if op == "=":
            return int(left == right)
        if op == "<>":
            return int(left != right)
        if op == "<":
            return int(left < right)
        if op == "<=":
            return int(left <= right)
        if op == ">":
            return int(left > right)
        return int(left >= right)

    cache = {}
    active = set()

    for root in cells:
        if root in cache:
            continue

        tasks = [("cell", root)]
        values = []

        while tasks:
            task = tasks.pop()
            action = task[0]

            if action == "cell":
                name = task[1]
                if name not in cells:
                    values.append(0)
                elif name in cache:
                    values.append(cache[name])
                elif name in active:
                    values.append("#CYCLE!")
                else:
                    content = cells[name]
                    if content.startswith("="):
                        node = parse(content[1:])
                        active.add(name)
                        tasks.append(("finish_cell", name))
                        tasks.append(("evaluate", node))
                    else:
                        value = integer(content)
                        cache[name] = value
                        values.append(value)

            elif action == "finish_cell":
                name = task[1]
                cache[name] = values[-1]
                active.remove(name)

            elif action == "evaluate":
                node = task[1]
                kind = node[0]

                if kind == "number":
                    values.append(node[1])
                elif kind == "reference":
                    tasks.append(("cell", node[1]))
                elif kind == "neg":
                    tasks.append(("negate",))
                    tasks.append(("evaluate", node[1]))
                elif kind == "IF":
                    condition, then_branch, else_branch = node[1]
                    tasks.append(("choose", then_branch, else_branch))
                    tasks.append(("evaluate", condition))
                elif kind in ("SUM", "MIN", "MAX"):
                    arguments = expanded_arguments(node[1])
                    tasks.append(("function_next", kind, arguments, None))
                else:
                    tasks.append(("binary_left", kind, node[2]))
                    tasks.append(("evaluate", node[1]))

            elif action == "negate":
                value = values.pop()
                values.append(value if isinstance(value, str) else -value)

            elif action == "binary_left":
                left = values.pop()
                if isinstance(left, str):
                    values.append(left)
                else:
                    tasks.append(("binary_right", task[1], left))
                    tasks.append(("evaluate", task[2]))

            elif action == "binary_right":
                right = values.pop()
                if isinstance(right, str):
                    values.append(right)
                else:
                    values.append(binary(task[1], task[2], right))

            elif action == "choose":
                condition = values.pop()
                if isinstance(condition, str):
                    values.append(condition)
                else:
                    branch = task[1] if condition else task[2]
                    tasks.append(("evaluate", branch))

            elif action == "function_next":
                _, function, arguments, accumulator = task
                argument = next(arguments, None)
                if argument is None:
                    values.append(0 if accumulator is None else accumulator)
                else:
                    tasks.append(
                        ("function_value", function, arguments, accumulator)
                    )
                    tasks.append(("evaluate", argument))

            elif action == "function_value":
                _, function, arguments, accumulator = task
                value = values.pop()
                if isinstance(value, str):
                    values.append(value)
                    continue

                if accumulator is None:
                    accumulator = value
                elif function == "SUM":
                    accumulator += value
                elif function == "MIN":
                    accumulator = min(accumulator, value)
                else:
                    accumulator = max(accumulator, value)

                tasks.append(
                    ("function_next", function, arguments, accumulator)
                )

    return {name: cache[name] for name in cells}
